WITH , scoped_interest AS ( SELECT DISTINCT plan.user_id, plan.category_id FROM (
) plan JOIN user_metrics metrics ON plan.user_id = metrics.user_id WHERE ) SELECT category.category_id AS categoryId, category.category_name AS categoryName, COUNT(interest.user_id) AS interestCount FROM roadmap_category category LEFT JOIN scoped_interest interest ON category.category_id = interest.category_id WHERE category.del_yn = 'N' GROUP BY category.category_id, category.category_name
ORDER BY interestCount DESC, category.category_id
